    30  const TiffIFD* AbstractTiffDecoder::getIFDWithLargestImage(TiffTag filter) const
    31  {
    32    std::vector<const TiffIFD*> ifds = mRootIFD->getIFDsWithTag(filter);
    33
    34    if (ifds.empty())
    35      ThrowRDE("No suitable IFD with tag 0x%04x found.", filter);
    36
    37    auto res = ifds[0];
    38    uint32 width = res->getEntry(IMAGEWIDTH)->getU32();
    39    for (auto ifd : ifds) {
    40      TiffEntry* widthE = ifd->getEntry(IMAGEWIDTH);
    41      // guard agains random maker note entries with the same tag
    42      if (widthE->count == 1 && widthE->getU32() > width) {
    43        res = ifd;
    44        width = widthE->getU32();
    45      }
    46    }
    47
    48    return res;
    49  }
